import { scope } from "arktype";
import { jsonSchemaToType } from "@ark/json-schema";
import * as fs from "fs";
import * as path from "path";

// 1. Define the original ArkType schema using scope({ ... }).export()
export const typesScope = scope({
  Comment: {
    id: "string.uuid",
    body: "string>=1",
    "replies?": "Comment[]"
  },
  Post: {
    title: "1<=string<=120",
    tags: "1<=string[]<=10",
    comments: "Comment[]"
  },
  User: {
    id: "string.uuid",
    email: "string.email",
    username: "string.alphanumeric & 3<=string<=20",
    score: ["string.numeric", "=>", (s: string) => Number(s)],
    address: {
      street: "string",
      city: "string",
      zip: /^\d{5}(-\d{4})?$/
    },
    posts: "Post[]"
  }
});

export const { User: userSchema } = typesScope.export();

// 2. Export JSON Schema functionality
export function exportUserJsonSchema(): object {
  const schema = userSchema.toJsonSchema({
    fallback: (node: any) => node.base
  });

  const outDir = "/home/user/myproject/out";
  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }
  fs.writeFileSync(
    path.join(outDir, "user.schema.json"),
    JSON.stringify(schema, null, 2),
    "utf-8"
  );

  return schema;
}

// Helper to dereference cyclic JSON Schema for @ark/json-schema
function dereference(schema: any, defs: any, currentPath: string[] = [], maxDepth = 5): any {
  if (schema === null || typeof schema !== "object") {
    return schema;
  }

  if (Array.isArray(schema)) {
    return schema.map(item => dereference(item, defs, currentPath, maxDepth));
  }

  if (schema.$ref) {
    const refKey = schema.$ref.replace("#/$defs/", "");
    const refSchema = defs[refKey];
    if (!refSchema) {
      throw new Error(`Unresolved ref: ${schema.$ref}`);
    }

    const occurrences = currentPath.filter(x => x === refKey).length;
    if (occurrences >= maxDepth) {
      const resolved = { ...refSchema };
      if (resolved.properties) {
        const props = { ...resolved.properties };
        delete props.replies;
        resolved.properties = props;
      }
      if (resolved.required) {
        resolved.required = resolved.required.filter((k: string) => k !== "replies");
      }
      return dereference(resolved, defs, [...currentPath, refKey], maxDepth);
    }

    return dereference(refSchema, defs, [...currentPath, refKey], maxDepth);
  }

  const result: any = {};
  for (const key of Object.keys(schema)) {
    if (key === "$defs") continue;
    result[key] = dereference(schema[key], defs, [...currentPath], maxDepth);
  }
  return result;
}

// 3. Build the round-tripped ArkType schema from the exported JSON Schema
const schemaObj = userSchema.toJsonSchema({
  fallback: (node: any) => node.base
});
const derefSchema = dereference(schemaObj, schemaObj.$defs);
export const roundTrippedUserSchema = jsonSchemaToType(derefSchema);

import * as fs from "fs";
import { userSchema, roundTrippedUserSchema, exportUserJsonSchema } from "./src/schema.js";

// Ensure the schema is exported to /home/user/myproject/out/user.schema.json
exportUserJsonSchema();

// Read all of stdin
const input = fs.readFileSync(0, "utf-8");
let payload: any;
try {
  payload = JSON.parse(input);
} catch (err) {
  // If the input is not valid JSON, treat it as invalid for both schemas
  console.log("INVALID");
  console.log(JSON.stringify({ original: false, roundtrip: false }));
  process.exit(0);
}

const originalValid = userSchema.allows(payload);
const roundtripValid = roundTrippedUserSchema.allows(payload);

console.log(originalValid ? "VALID" : "INVALID");
console.log(JSON.stringify({ original: originalValid, roundtrip: roundtripValid }));
process.exit(0);

import { execSync } from "child_process";

const validPayload = {
  id: "123e4567-e89b-12d3-a456-426614174000",
  email: "test@example.com",
  username: "abc12",
  score: "100",
  address: { street: "123 Main St", city: "NY", zip: "12345" },
  posts: [
    {
      title: "A great post",
      tags: ["cool", "stuff"],
      comments: [
        {
          id: "123e4567-e89b-12d3-a456-426614174001",
          body: "First comment",
          replies: [
            {
              id: "123e4567-e89b-12d3-a456-426614174002",
              body: "Reply 1",
              replies: [
                {
                  id: "123e4567-e89b-12d3-a456-426614174003",
                  body: "Reply 2"
                }
              ]
            }
          ]
        }
      ]
    }
  ]
};

const validPayloadNoComments = {
  ...validPayload,
  posts: [
    {
      title: "A great post",
      tags: ["cool"],
      comments: []
    }
  ]
};

const badEmail = JSON.parse(JSON.stringify(validPayload));
badEmail.email = "not-an-email";

const badZip = JSON.parse(JSON.stringify(validPayload));
badZip.address.zip = "abcde";

const badUsername = JSON.parse(JSON.stringify(validPayload));
badUsername.username = "ab";

const longTitle = JSON.parse(JSON.stringify(validPayload));
longTitle.posts[0].title = "x".repeat(200);

const tooManyTags = JSON.parse(JSON.stringify(validPayload));
tooManyTags.posts[0].tags = Array(11).fill("tag");

const testCases = [
  { name: "1. Valid payload with depth-3 comments", payload: validPayload, expectedLine1: "VALID", expectedLine2: { original: true, roundtrip: true } },
  { name: "2. Valid payload with no comments", payload: validPayloadNoComments, expectedLine1: "VALID", expectedLine2: { original: true, roundtrip: true } },
  { name: "3. Bad email", payload: badEmail, expectedLine1: "INVALID", expectedLine2: { original: false, roundtrip: false } },
  { name: "4. Bad zip", payload: badZip, expectedLine1: "INVALID", expectedLine2: { original: false, roundtrip: false } },
  { name: "5. Bad username", payload: badUsername, expectedLine1: "INVALID", expectedLine2: { original: false, roundtrip: false } },
  { name: "6. Long title", payload: longTitle, expectedLine1: "INVALID", expectedLine2: { original: false, roundtrip: false } },
  { name: "7. Too many tags", payload: tooManyTags, expectedLine1: "INVALID", expectedLine2: { original: false, roundtrip: false } },
];

let allPassed = true;

for (const tc of testCases) {
  console.log(`Running: ${tc.name}`);
  try {
    const inputStr = JSON.stringify(tc.payload);
    const output = execSync("npx --no-install tsx cli.ts", {
      input: inputStr,
      encoding: "utf-8"
    });

    const lines = output.trim().split("\n");
    if (lines.length !== 2) {
      console.error(`  FAIL: Expected exactly 2 lines of output, got ${lines.length}`);
      console.error(`  Output:\n${output}`);
      allPassed = false;
      continue;
    }

    const line1 = lines[0].trim();
    const line2 = JSON.parse(lines[1].trim());

    if (line1 !== tc.expectedLine1) {
      console.error(`  FAIL: Line 1 expected "${tc.expectedLine1}", got "${line1}"`);
      allPassed = false;
    } else {
      console.log(`  Line 1 OK: ${line1}`);
    }

    if (JSON.stringify(line2) !== JSON.stringify(tc.expectedLine2)) {
      console.error(`  FAIL: Line 2 expected ${JSON.stringify(tc.expectedLine2)}, got ${JSON.stringify(line2)}`);
      allPassed = false;
    } else {
      console.log(`  Line 2 OK: ${JSON.stringify(line2)}`);
    }
  } catch (err: any) {
    console.error(`  FAIL: CLI crashed or returned non-zero exit code:`, err.message);
    if (err.stdout) console.error("stdout:", err.stdout);
    if (err.stderr) console.error("stderr:", err.stderr);
    allPassed = false;
  }
}

if (allPassed) {
  console.log("\nALL TESTS PASSED!");
} else {
  console.error("\nSOME TESTS FAILED!");
  process.exit(1);
}

